od INCLUDES \\"audit\\":\\nLOOKUP(auditFrequency, {\\n\\"annual\\": 5,\\n\\"bi_annual\\""}]}, "formula_vendor_trust_score": 87.18, "category_coverage_resolution": {"vector": {"used": true, "error": null, "pgvector_hits": {"Human Oversight Mechanisms": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.3765}, "Model Security & Integrity": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.4439}, "Post-Deployment Monitoring": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.3926}, "Incident Response & Recovery": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.4675}, "Transparency & Documentation": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.4753}, "Testing & Auditing Procedures": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.4733}, "Compliance & Regulatory Adherence": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.5174}, "Access Management & Authentication": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.4542}, "Data Governance & Privacy Controls": {"files": ["AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf"], "best_score": 0.4202}}, "attestation_similarities": 