score": {"value": 5, "coverage_points": 0, "expertise_points": 1, "support_tier_points": 4}, "stability_score": {"value": 21, "company_age_years": 13, "company_age_points": 12, "financial_health_points": 5, "customer_retention_points": 4}, "operational_score": 64, "raw_operational_score": 64, "deployment_maturity_score": {"value": 14, "scale_points": 7, "multi_tenancy_points": 6, "production_readiness_points": 1}, "incident_management_score": {"value": 15, "plan_points": 10, "automation_points": 0, "communication_points": 5}}, "vector_retrieval": {"used": true, "error": null, "chunks": [{"id": "7fd58480-1f48-4922-a0db-9764d8cd0335", "score": 0.5020880848791627, "file_name": "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "chunk_index": 13, "content_preview": "├─ Incident Management: 30 points (automated + tested)\\n├─ Deployment Maturity: 30 points (enterprise multi-tenant)\\n├─ Stability: 22 points (8-year company, profitable)\\n├─ Support: 20 points (24/7 dedicated support)\\n├─ Operational Score: 100"}, {"id": "aa47a4b9-ef6f-4a92-a2ec-ae0bd90e7024", "score": 0.44233869188014774, "file_name": "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "chunk_index": 1, "content_preview": "supports sales enablement by estimating the difficulty of closing a specific deal via a Sales Confidence\\nScore (0–100, higher = stronger deal) that blends Customer Friction Risk (35%), Implementation Risk\\n(35%), and Competitive Risk (30%), "}, {"id": "4884fd64-a648-41e5-92be-2686512eca74", "score": 0.3971088348957551, "file_name": "AI EVAL Risk Scoring Technical Specification Part 1 (1).pdf", "chunk_index": 12, "content_preview": "Expertise:\\n- technicalAccountManager = \\"dedicated_tam\\" → 5 points\\nSupport_Score = 10 + 5 + 5 = 20 points\\n1.4.7 Final Operational Risk\\nFormula:\\nOperational_Score = SLA + Incident_Management + Deployment_Maturity +\\nStability + Support\\nOperati"}, {"id": "3aeebc49-eb86-4850-99dd-9459b23811a9", "score": 0.3338909546700